const fs = require('fs');

function nextPermutation(arr) {
    const n = arr.length;
    for (let i = n - 1; i >= 1; i--) {
        if (arr[i] > arr[i - 1]) {
            [arr[i], arr[i - 1]] = [arr[i - 1], arr[i]];
            // sort suffix ascending
            arr.splice(i, n - i, ...arr.slice(i).sort((a, b) => a - b));
            return true;
        }
    }
    return false;
}

function main() {
    const input = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/).map(Number);
    const n = input[0];
    const a = input[1];
    const b = input[2];

