    const idxs = new Array(6);
    for (let i = 0; i < 6; i++) {
        frames[i] = i < 4 ? a : b;
        idxs[i] = i;
    }

    let bestAnswer = 6;
    while (true) {
        let count = 0;
        let leftover = 0;
        for (let i = 0; i < 6; i++) {
            if (leftover < frames[idxs[i]]) {
                count++;
                leftover = n;
            }
            leftover -= frames[idxs[i]];
        }
        if (count < bestAnswer) {
            bestAnswer = count;
        }
        if (!nextPermutation(idxs)) {
            break;
        }
    }

    console.log(bestAnswer);
}

